def compute(vars):
    claims_payable = vars["v1"]
    total_contractual_obligations = vars["v2"]

    if total_contractual_obligations == 0:
        return None

    ratio = claims_payable / total_contractual_obligations
    percentage = ratio * 100

    return {
        "value": percentage,
        "trace": {
            "claims_payable": claims_payable,
            "total_contractual_obligations": total_contractual_obligations,
            "ratio": ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
